/// 骑行详情底部的指标区：一排胶囊切换指标，下面只留这一张图。
///
/// 以前心率 / 踏频 / 功率 / 速度各占一张卡，一屏只看得见一张，想比一下
/// 平均值得来回滚。现在用胶囊把「看哪个指标」显式化：图的位置不变，切换
/// 只换数据，眼睛不用重新找地方。
class RideMetricSection extends StatefulWidget {
  /// 创建指标区。
  const RideMetricSection({
    super.key,
    required this.summary,
    this.cursor,
  });

  /// 本次骑行的解析结果；null 时只能显示空态。
  final GpxSummary? summary;

  /// 回放游标，0..1；null 表示没在回放。
  final ValueListenable<double?>? cursor;

  @override
  State<RideMetricSection> createState() => _RideMetricSectionState();
}

/// 四种指标。顺序即胶囊顺序，也是「默认选中第一个可用」的优先级。
enum _Metric { hr, cadence, power, speed }

class _RideMetricSectionState extends State<RideMetricSection> {
  static const _hrColor = Color(0xFFFF5C4D);
  static const _cadenceColor = Color(0xFF34D399);
  static const _powerColor = Color(0xFFFFA733);
  static const _speedColor = Color(0xFF3DDC84);

  /// 五区配色，与详情页心率卡保持一致（同一个区不能两处两个颜色）。
  static const _zoneColors = [
    Color(0xFF5B8DEF),
    Color(0xFF3DDC84),
    Color(0xFFFFD54A),
    Color(0xFFFF8A3D),
    Color(0xFFFF4D4D),
  ];

  /// 当前选中的胶囊；null 表示四个指标都不可用。
  _Metric? _selected;

  @override
  void initState() {
    super.initState();
    _selected = _firstAvailable(widget.summary);
  }

  @override
  void didUpdateWidget(covariant RideMetricSection old) {
    super.didUpdateWidget(old);
    /// 换了记录（或数据补齐）后，原来的选中项可能已经不存在了：重挑一个，
    /// 否则会画出一张空图。didUpdateWidget 之后紧跟着 build，不用 setState。
    if (_selected == null || !_available(_selected!, widget.summary)) {
      _selected = _firstAvailable(widget.summary);
    }
  }

  /// 指标是否可用。不可用的胶囊仍然显示，只是压暗且点不动 ——
  /// 直接藏掉会让人以为界面漏了，而不是「这次没戴传感器」。
  static bool _available(_Metric m, GpxSummary? s) {
    if (s == null) return false;
    return switch (m) {
      _Metric.hr => s.hasHr,
      _Metric.cadence => s.hasCadence,
      _Metric.power => s.hasPower,
      _Metric.speed => s.speedPoints.isNotEmpty || s.avgSpeedKmh != null,
    };
  }

  static _Metric? _firstAvailable(GpxSummary? s) {
    for (final m in _Metric.values) {
      if (_available(m, s)) return m;
    }
    return null;
  }

  static String _label(_Metric m) => switch (m) {
        _Metric.hr => LocaleKeys.rideMetricHr,
        _Metric.cadence => LocaleKeys.rideCadenceCard,
        _Metric.power => LocaleKeys.ridePowerCard,
        _Metric.speed => LocaleKeys.rideSpeedCard,
      }.tr;

  static Color _color(_Metric m) => switch (m) {
        _Metric.hr => _hrColor,
        _Metric.cadence => _cadenceColor,
        _Metric.power => _powerColor,
        _Metric.speed => _speedColor,
      };

  /// 取逐点序列的原始值。去尖峰 / 平滑统一在 [RideSeriesChart] 里做，
  /// 这里不再预加工 —— 两处都处理会让曲线和统计对不上。
  static List<double> _values(_Metric m, GpxSummary s) {
    switch (m) {
      case _Metric.hr:
        return [for (final p in s.hrPoints) p.value];
      case _Metric.cadence:
        return [for (final p in s.cadPoints) p.value];
      case _Metric.power:
        return [for (final p in s.powerPoints) p.value];
      case _Metric.speed:
        final v = [for (final p in s.speedPoints) p.value];
        final avg = s.avgSpeedKmh;
        /// 老记录 / 极短骑行可能只有均值没有逐点速度：两点平线至少让
        /// 图表区域有内容，而不是一片空白。
        return v.isEmpty && avg != null ? [avg, avg] : v;
    }
  }

  static double? _avg(_Metric m, GpxSummary s) => switch (m) {
        _Metric.hr => s.avgHrBpm?.toDouble(),
        _Metric.cadence => s.avgCadenceRpm?.toDouble(),
        _Metric.power => s.avgPowerW,
        _Metric.speed => s.avgSpeedKmh,
      };

  /// 统计值：心率是整数 BPM，踏频 / 功率取整，速度保留一位小数。
  static ({String avg, String max}) _stats(_Metric m, GpxSummary s) {
    final dash = LocaleKeys.rideStatDash.tr;
    String intOf(num? v) => v == null ? dash : '${v.round()}';
    return switch (m) {
      _Metric.hr => (
          avg: intOf(s.avgHrBpm),
          max: intOf(s.maxHrBpm),
        ),
      _Metric.cadence => (
          avg: intOf(s.avgCadenceRpm),
          max: intOf(s.maxCadenceRpm),
        ),
      _Metric.power => (
          avg: intOf(s.avgPowerW),
          max: intOf(s.maxPowerW),
        ),
      _Metric.speed => (
          avg: s.avgSpeedKmh?.toStringAsFixed(1) ?? dash,
          max: s.maxSpeedKmh?.toStringAsFixed(1) ?? dash,
        ),
    };
  }

  static ({String avg, String max}) _statLabels(_Metric m) => switch (m) {
        _Metric.hr => (
            avg: LocaleKeys.rideMetricAvgHr.tr,
            max: LocaleKeys.rideMetricMaxHr.tr,
          ),
        _Metric.cadence => (
            avg: LocaleKeys.rideMetricAvgCadence.tr,
            max: LocaleKeys.rideMetricMaxCadence.tr,
          ),
        _Metric.power => (
            avg: LocaleKeys.rideMetricAvgPower.tr,
            max: LocaleKeys.rideMetricMaxPower.tr,
          ),
        _Metric.speed => (
            avg: LocaleKeys.rideMetricAvgSpeed.tr,
            max: LocaleKeys.rideMetricMaxSpeed.tr,
          ),
      };

  @override
  Widget build(BuildContext context) {
    final sum = widget.summary;
    final available = [
      for (final m in _Metric.values)
        if (_available(m, sum)) m,
    ];
    if (sum == null || available.isEmpty) {
      return HelmCard(
        padding: const EdgeInsets.fromLTRB(18, 14, 18, 14),
        child: Text(
          LocaleKeys.rideMetricEmpty.tr,
          style: const TextStyle(color: AppTheme.muted, fontSize: 13),
        ),
      );
    }

    /// 选中项在 summary 换过之后可能已不可用；didUpdateWidget 会重挑，
    /// 这里再兜一层，保证任何构建顺序下都不会拿到一张空图。
    final metric = _selected != null && available.contains(_selected)
        ? _selected!
        : available.first;

    final values = _values(metric, sum);
    final avg = _avg(metric, sum);
    final color = _color(metric);
    final value = _stats(metric, sum);
    final labels = _statLabels(metric);

    /// 只有图表跟着游标逐帧重建：胶囊和统计每帧重建一次纯属浪费，
    /// 而回放时这里可能一秒推 60 次。
    Widget chart(double? cursor) => SizedBox(
          height: 132,
          width: double.infinity,
          child: RideSeriesChart(
            values: values,
            color: color,
            fill: true,
            avg: avg,
            cursor: cursor,
          ),
        );
    final listenable = widget.cursor;
    final chartBox =
        listenable == null ? chart(null) : ValueListenableBuilder<double?>(
            valueListenable: listenable,
            builder: (context, cursor, _) => chart(cursor),
          );

    return HelmCard(
      padding: const EdgeInsets.fromLTRB(18, 14, 18, 14),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                for (var i = 0; i < _Metric.values.length; i++) ...[
                  if (i > 0) const SizedBox(width: 8),
                  _MetricPill(
                    label: _label(_Metric.values[i]),
                    color: _color(_Metric.values[i]),
                    selected: _Metric.values[i] == metric,
                    enabled: available.contains(_Metric.values[i]),
                    onTap: () =>
                        setState(() => _selected = _Metric.values[i]),
                  ),
                ],
              ],
            ),
          ),
          const SizedBox(height: 12),
          chartBox,
          const SizedBox(height: 4),
          Row(
            children: [
              Expanded(
                child: _MetricStat(value: value.avg, label: labels.avg),
              ),
              Expanded(
                child: _MetricStat(value: value.max, label: labels.max),
              ),
            ],
          ),
          if (metric == _Metric.hr) ...[
            const SizedBox(height: 12),
            ..._hrZones(sum),
          ],
        ],
      ),
    );
  }

  /// 心率的五区时长条。时长按心率采样点的时间戳累加，与详情页心率卡
  /// 同一个算法，两处的区时长才对得上。
  List<Widget> _hrZones(GpxSummary s) {
    final zones = GpxUtil.hrZoneDurations(s.hrPoints, total: s.duration);
    final maxMs = zones.fold<int>(
      0,
      (m, d) => d.inMilliseconds > m ? d.inMilliseconds : m,
    );
    final names = [
      LocaleKeys.rideZoneWarmup.tr,
      LocaleKeys.rideZoneFat.tr,
      LocaleKeys.rideZoneAerobic.tr,
      LocaleKeys.rideZoneAnaerobic.tr,
      LocaleKeys.rideZoneExtreme.tr,
    ];
    return [
      for (var i = 0; i < 5; i++)
        RideZoneBar(
          label: names[i],
          color: _zoneColors[i],
          time: zones[i],
          maxMs: maxMs < 1 ? 1 : maxMs,
        ),
    ];
  }
}

/// 指标胶囊。未选是中性深灰，选中用指标自己的颜色描边 + 半透明底，
/// 让「图是什么颜色」和「当前看的是哪个指标」是同一件事。
class _MetricPill extends StatelessWidget {
  const _MetricPill({
    required this.label,
    required this.color,
    required this.selected,
    required this.enabled,
    required this.onTap,
  });

  final String label;
  final Color color;
  final bool selected;
  final bool enabled;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final pill = GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: enabled ? onTap : null,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 7),
        decoration: BoxDecoration(
          color: selected
              ? color.withValues(alpha: 0.18)
              : const Color(0xFF2C2C2E),
          borderRadius: BorderRadius.circular(999),
          border: selected ? Border.all(color: color) : null,
        ),
        child: Text(
          label,
          style: TextStyle(
            color: selected ? color : const Color(0xFFAEAEB2),
            fontSize: 12,
            fontWeight: selected ? FontWeight.w700 : FontWeight.w500,
          ),
        ),
      ),
    );
    /// 不可用整颗压暗：仍要占位，让人知道「这次没这个传感器」。
    return enabled ? pill : Opacity(opacity: 0.35, child: pill);
  }
}

