          ? Center(child: Text(LocaleKeys.rideEmpty.tr))
          : LayoutBuilder(
              builder: (context, box) {
                final h = box.maxHeight;
                final bottom = MediaQuery.paddingOf(context).bottom;
                return AnimatedBuilder(
                  animation: _sheet,
                  builder: (context, _) {
                    // `animateTo(curve:)` 已经把曲线作用在 value 上了；这里再
                    // transform 一次等于开方后又开方，拖拽时抽屉还不跟手
                    // （手指走 100 px，抽屉只走 62 px）。直接用线性值。
                    final t = _sheet.value;
                    final peekH = _peekBody + bottom * (1 - t);
                    final sheetH = peekH + (h * 0.5 - peekH) * t;
                    return Stack(
                      children: [
                        Column(
                          children: [
                            Expanded(
                              child: Stack(
                                fit: StackFit.expand,
                                children: [
                                  _mapView(
                                    _map,
                                    fitPad: t < 0.5 ? _mapPadPeek : _mapPad,
                                    playable: true,
                                  ),
                                  if (t < 0.98)
                                    IgnorePointer(
                                      child: Opacity(
